import axios from 'axios';
  
import {
  fetchMyFollowers
  } from '../actions/myFollowersSearchActions'

import {
  fetchReceivedMessages
  } from '../actions/receivedMessagesSearchActions'
    
import {
  fetchSentMessages
  } from '../actions/sentMessagesSearchActions'

import {
  fetchRecentCommentersSearches
  } from '../actions/commentersSearchActions'

import {
  fetchRecentFollowersSearches
  } from '../actions/followersSearchActions'
  
export const AUTH_HTTP_ERROR = 'AUTH_HTTP_ERROR'
export const AUTH_SESSION_ERROR = 'AUTH_SESSION_ERROR'
export const AUTH_COOKIE_ERROR = 'AUTH_COOKIE_ERROR'
export const AUTH_SUCCESS = 'AUTH_SUCCESS'
export const AUTH_UNKNOWN_ERROR = 'AUTH_UNKNOWN_ERROR'


export const fetchAuth = (dispatch) => {
    //dispatch(requestAuth())
    
      axios.get('https://scbm.amfdev.co.uk/api/auth/', { headers: { "X-Request-App": "scbm" } })
      .then(json => dispatch(catchAuthSessionError(json.data, dispatch)))
      .then(json => dispatch(catchAuthCookieError(json, dispatch)))
      .then(json => dispatch(doAuthSuccess(json, dispatch)))
      //.then(json => dispatch(fetchReceivedMessages()))
      //.then(json => dispatch(fetchSentMessages()))
      //.then(json => dispatch(fetchMyFollowers()))
      //.then(json => dispatch(fetchRecentCommentersSearches()))
      //.then(json => dispatch(fetchRecentFollowersSearches()))
      .catch(error => {

                if (error.response) {   
                      dispatch({
                          type: AUTH_UNKNOWN_ERROR
                      })  
                }
      });


}


export const catchAuthSessionError = (json, dispatch) => {
    //console.log('catchAuthSessionError')
    if (!json.sessionValid) {
        
          dispatch({
                type: AUTH_SESSION_ERROR
              });
          
        throw Error(json.authError);
    }
    
  return json;
}

export const catchAuthCookieError = (json, dispatch) => {
   //console.log('catchAuthCookieError')
    if (!json.scCookiesValid) {
           dispatch({
                type: AUTH_COOKIE_ERROR
              });
        throw Error(json.authError);
    }
    
  return json;
}


export const doAuthSuccess = (json, dispatch) => {
  console.log("authActions doAuthSuccess - JSON.parse(json.userData.userSettings): ")
  console.log(JSON.parse(json))
    if (json.authSuccess) {
    console.log("doing dispatch")
        dispatch({
          type: "AUTH_SUCCESS",
          userData: json.userData,
          userSettings: JSON.parse(json.userData.userSettings)
        })
            
    }
    
  return    dispatch({
          type: "AUTH_SUCCESS",
          userData: json.userData,
          userSettings: JSON.parse(json.userData.userSettings)
        });
}
